style.css:
@-moz-document url-prefix("http"), url-prefix("https") {
html, body {
        background: url("https://i.redd.it/3psm9bq2t32e1.jpeg") no-repeat center center fixed !important;
        background-size: cover !important;
        height: 100%;
        margin: 0;
        padding: 0;
    }

    /* Make backgrounds transparent to show wallpaper */
    * {
        background-color: transparent !important;
        background-image: none !important;
    }
}
